// Check the parent actually handed us a slide, and say something useful when it
// did not. Nothing here calls an API, so this costs nothing and runs in ~1 ms.
//
// Why this node exists (executions 599-602, 2026-08-26): the HTTP node builds its
// body with JSON.stringify({ contents: [{ parts: [{ text: $json.image_prompt }] }] }).
// JSON.stringify DROPS a key whose value is undefined, so a missing image_prompt
// posts parts: [{}] and Gemini answers
//   400 * GenerateContentRequest.contents[0].parts[0].data:
//        required oneof field 'data' must have one initialized field
// which names neither the field that was missing nor the workflow that omitted
// it. An empty string does the same thing -- protobuf treats "" in a oneof as
// unset. Three attempts were burned on that before anyone could see why.
const REQUIRED = ['image_prompt', 'author_urn', 'linkedin_version', 'image_aspect', 'image_size'];

return $input.all().map(function (item, i) {
  const j = item.json || {};

  const missing = REQUIRED.filter(function (k) {
    return typeof j[k] !== 'string' ? j[k] == null : !j[k].trim();
  });
  // slide_index is legitimately 0, so it cannot be checked for falsiness.
  if (j.slide_index === undefined || j.slide_index === null) missing.push('slide_index');

  if (missing.length) {
    // n8n substitutes this placeholder for every node's data when a worker dies,
    // and the editor keeps showing it on the canvas afterwards. Running a single
    // node with "Test step" then feeds the placeholder into it as real input.
    const stale = j.isArtificialRecoveredEventItem
      ? ' The input is n8n\'s placeholder for a crashed execution, so this was started from stale canvas data — ' +
        'run the parent workflow from its trigger rather than testing this node on its own.'
      : ' Input item ' + i + ' had keys: [' + Object.keys(j).join(', ') + '].';

    throw new Error(
      'Render LinkedIn Slide (sub) was called without: ' + missing.join(', ') + '.' + stale +
      ' Nothing was sent to Gemini and nothing was uploaded.'
    );
  }

  return item;
});

// Pull the inline image out of the Gemini envelope and hand it downstream as a
// binary named "data".
//
// THE RESPONSE ARRIVES AS A FILE, NOT AS JSON. "Generate Slide Image" is set to
// responseFormat: "file", and that is the whole memory fix (execution 595,
// 2026-08-26, crashed the worker on slide 2 of 4). A JSON response puts ~3.4 MB
// of base64 into this execution's runData, which n8n holds in RAM for the entire
// run -- and it was held TWICE, once on the HTTP node and once on the IF node
// that read it. ~15 MB retained per slide, ~30 MB of V8 heap, times a carousel.
// A binary response is spooled to the filesystem and costs runData nothing.
//
// This node also owns the refusal check now, which is why it sits BEFORE
// "Has Image?" rather than after it. It must therefore never throw on a refusal:
// it emits { ok: false, reason } and lets "Has Image?" route to the retry, since
// Gemini answers 200-with-no-image on roughly one call in five.

function extractImage(json) {
  const cands = (json && json.candidates) || [];
  for (const cand of cands) {
    const parts = (cand && cand.content && cand.content.parts) || [];
    for (const p of parts) {
      const inline = p.inlineData || p.inline_data;
      if (inline && inline.data) {
        return { data: inline.data, mime: inline.mimeType || inline.mime_type || 'image/png' };
      }
    }
  }
  return null;
}

function extFor(mime) {
  if (mime.indexOf('jpeg') !== -1 || mime.indexOf('jpg') !== -1) return 'jpg';
  if (mime.indexOf('webp') !== -1) return 'webp';
  return 'png';
}

// Never put the raw payload in the returned json -- that is the base64 coming
// straight back into runData through the side door.
function describe(json) {
  const j = json || {};
  const cand = (j.candidates || [])[0] || {};
  const bits = [];
  if (cand.finishReason) bits.push('finishReason=' + cand.finishReason);
  if (j.promptFeedback && j.promptFeedback.blockReason) bits.push('blockReason=' + j.promptFeedback.blockReason);
  if (j.error) bits.push('httpError=' + JSON.stringify(j.error).slice(0, 200));
  if (!bits.length) bits.push('no image part and no reason given; top-level keys: ' + Object.keys(j).join(','));
  return bits.join(' | ').slice(0, 400);
}

const cfg = $('When Executed by Parent').first().json;
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  let payload = null;
  let failure = '';

  if ((items[i].binary || {}).response) {
    try {
      const raw = await this.helpers.getBinaryDataBuffer(i, 'response');
      payload = JSON.parse(raw.toString('utf8'));
    } catch (e) {
      failure = 'the Gemini response could not be read or parsed: ' + String(e && e.message ? e.message : e).slice(0, 200);
    }
  } else {
    // "Generate Slide Image" is onError: continueRegularOutput, so a transport
    // failure or a 4xx/5xx arrives here as a plain json item carrying `error`
    // and no binary at all.
    payload = items[i].json || {};
  }

  const img = failure ? null : extractImage(payload);

  if (!img) {
    out.push({
      json: {
        ok: false,
        slideIndex: cfg.slide_index,
        reason: failure || describe(payload)
      }
    });
    continue;
  }

  const buf = Buffer.from(img.data, 'base64');

  // LinkedIn rejects images over 10 MB on the Images API. 1:1 @ 2K lands well
  // under that, but route an oversize frame back through the retry rather than
  // failing the slide -- a fresh generation is usually smaller, and if three in
  // a row are not, Retry Guard reports this reason.
  if (buf.length > 10 * 1024 * 1024) {
    out.push({
      json: {
        ok: false,
        slideIndex: cfg.slide_index,
        reason: 'image is ' + Math.round(buf.length / 1048576) + ' MB, over LinkedIn\'s 10 MB limit. ' +
          'If this repeats, drop IMAGE_SIZE from 2K to 1K in the parent Config node.'
      }
    });
    continue;
  }

  const fileName = 'slide-' + cfg.slide_index + '-' + $execution.id + '.' + extFor(img.mime);
  const bin = await this.helpers.prepareBinaryData(buf, fileName, img.mime);

  out.push({
    json: {
      ok: true,
      slideIndex: cfg.slide_index,
      altText: cfg.alt_text,
      authorUrn: cfg.author_urn,
      linkedinVersion: cfg.linkedin_version,
      fileName: fileName,
      mime: img.mime,
      bytes: buf.length
    },
    binary: { data: bin }
  });
}

return out;

// Gemini answers HTTP 200 with no image on roughly one call in five (measured on
// the Instagram engine: 2 refusals across 11 calls, either promptFeedback
// .blockReason=OTHER or a candidate with finishReason=OTHER and no inline part).
//
// retryOnFail on the HTTP node cannot help with that -- the call SUCCEEDED, so
// there is nothing for n8n to retry. Looping back to the generator is the only
// thing that makes a genuinely new call. Doing it here, inside the per-slide
// sub-workflow, retries just the slide that was refused; putting the retry on the
// parent's Execute Workflow node would regenerate every slide in the carousel.
//
// The input here is now "Convert Base64 to Binary"'s small { ok:false, reason }
// item, not the raw Gemini envelope -- the envelope never reaches runData any
// more, which is what keeps a carousel inside the worker's memory.
const MAX_ATTEMPTS = 3;

const j = $input.first().json || {};

if ($runIndex + 1 >= MAX_ATTEMPTS) {
  throw new Error(
    'Gemini returned no usable image after ' + MAX_ATTEMPTS + ' attempts for slide ' +
    ($('When Executed by Parent').first().json.slide_index) + '. Last reason: ' + (j.reason || 'unknown')
  );
}

// Re-feed the ORIGINAL trigger item, not $input -- $input here is the failure
// record, which has no image_prompt on it.
return $('When Executed by Parent').all();

// Re-read everything by NODE REFERENCE, never off $input.
//
// The PUT above and the Drive node both emit their own API response and drop the
// upstream json, so reading $input here would return a populated-looking item
// with none of the fields we care about. That exact mistake returned "{}" to the
// parent on the Instagram engine (execution 383) and surfaced two nodes later as
// an opaque "Bad request" from the publish call.
//
// Returning json only (no binary) is the whole point of this node: Execute
// Workflow copies whatever the last node emits, so passing the image back would
// undo the memory saving this sub-workflow exists to provide.
const init = $('LinkedIn: Initialize Upload').all();
// NOT $('Convert Base64 to Binary') -- that node runs once per generation
// attempt, so a node reference to it can resolve to a refused attempt. The
// trigger runs exactly once and is where all of this came from anyway.
const cfg = $('When Executed by Parent').first().json;

let drive = [];
try { drive = $('Upload Preview to Drive').all(); } catch (e) { drive = []; }

return $input.all().map(function (item, i) {
  const iv = (((init[i] || init[0] || {}).json) || {}).value || {};
  const dj = ((drive[i] || drive[0] || {}).json) || {};

  if (!iv.image) {
    throw new Error('LinkedIn initializeUpload returned no image URN for slide ' +
      cfg.slide_index + '. Response: ' + JSON.stringify((init[i] || init[0] || {}).json).slice(0, 400));
  }

  return {
    json: {
      imageUrn: iv.image,
      slideIndex: cfg.slide_index,
      altText: cfg.alt_text,
      previewUrl: dj.webViewLink || null
    }
  };
});
